from enum import IntEnum
from roman import to_roman, is_roman_numeral

thousands = ('', 'M', 'MM', 'MMM')
hundreds = ('', 'C', 'CC', 'CCC', 'CD', 'D', 'DC', 'DCC', 'DCCC', 'CM')
tens = ('', 'X', 'XX', 'XXX', 'XL', 'L', 'LX', 'LXX', 'LXXX', 'XC')
units = ('', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX')
for n in range(1, 4000):
    expected = thousands[n // 1000] + hundreds[n // 100 % 10] + tens[n // 10 % 10] + units[n % 10]
    assert to_roman(n) == expected
class PlainInt(int):
    pass
class Number(IntEnum):
    FORTY_NINE = 49
assert to_roman(PlainInt(49)) == to_roman(Number.FORTY_NINE) == 'XLIX'
for n in (0, -1, 4000, PlainInt(0), PlainInt(-1), PlainInt(4000)):
    try:
        to_roman(n)
    except ValueError:
        pass
    else:
        raise AssertionError(f'Expected ValueError for {n!r}')
for n in ('5', 5.0, None, [1]):
    try:
        to_roman(n)
    except TypeError:
        pass
    else:
        raise AssertionError(f'Expected TypeError for {n!r}')
assert is_roman_numeral('IIII') and is_roman_numeral('mmxxiv')
print('Contract checks passed')
